class ClassRegistrationSystem:

    def __init__(self):
        self._students = []
        self._students_registration_classes = {}

    # Encapsulated field accessors
    def get_students(self):
        return list(self._students)

    def get_students_registration_classes(self):
        return {k: list(v) for k, v in self._students_registration_classes.items()}

    def register_student(self, student):
        if self._is_student_registered(student):
            return 0
        self._students.append(student)
        return 1

    def _is_student_registered(self, student):
        return student in self._students

    def register_class(self, student_name, class_name):
        if self._has_student_registration(student_name):
            self._students_registration_classes[student_name].append(class_name)
        else:
            self._students_registration_classes[student_name] = [class_name]
        return self._get_students_classes(student_name)

    def _has_student_registration(self, student_name):
        return student_name in self._students_registration_classes

    def _get_students_classes(self, student_name):
        if self._has_student_registration(student_name):
            return self._students_registration_classes[student_name]
        return []

    def get_students_by_major(self, major):
        return self._filter_students_by_major(major)

    def _filter_students_by_major(self, major):
        return [student["name"] for student in self._students if student["major"] == major]

    def get_all_major(self):
        return self._extract_unique_majors()

    def _extract_unique_majors(self):
        majors = set()
        for student in self._students:
            majors.add(student["major"])
        return list(majors)

    def get_most_popular_class_in_major(self, major):
        class_list = self._collect_classes_for_major(major)
        most_popular_class = self._find_most_popular_class(class_list)
        return most_popular_class

    def _collect_classes_for_major(self, major):
        class_list = []
        for student in self._students:
            if student["major"] == major:
                student_name = student["name"]
                if self._has_student_registration(student_name):
                    class_list += self._students_registration_classes[student_name]
        return class_list

    def _find_most_popular_class(self, class_list):
        if not class_list:
            return None
        return max(set(class_list), key=class_list.count)
